/**
 * Interchangeable media storage. HCG ADS never assumes a particular backend:
 * local development storage and HCG Server both implement this interface.
 */
export interface StorageProvider {
  readonly name: string;
  readonly description: string;
  status(): Promise<{ ok: boolean; message: string }>;
  put(key: string, data: Buffer, contentType: string): Promise<void>;
  get(key: string): Promise<Buffer | null>;
  delete(key: string): Promise<void>;
  usage(): Promise<{ bytes: number; objects: number } | null>;
}

/** Keys are generated by HCG ADS only; this guards against traversal anyway. */
export function assertSafeKey(key: string): void {
  if (!/^[a-z0-9][a-z0-9/_.-]{0,300}$/i.test(key) || key.includes("..") || key.includes("//")) {
    throw new Error(`Unsafe storage key: ${key}`);
  }
}
